  "admin.permissionWarnings.archive": "サイト内アーカイブを公開するには、{permissions}も必要です。",
  "admin.permissionWarnings.merge": "作品の統合には、{permissions}も必要です。",
  "admin.permissionWarnings.dependency": "「{permission}」の管理機能をすべて使うには「{required}」も必要です。",
  "admin.permissionWarnings.wiki": "作者とキャラクターの情報、タグ、作品の関連付け、キャラクター分類、出典、素材を管理します。変更はすぐに反映され、操作履歴に記録されます。",
  "permission.description.message.send": "ダイレクトメッセージを受け付ける有効なユーザーに、テキスト、絵文字、または画像1枚を送信できます。履歴は会話の当事者のみ閲覧できます。",
  "permission.description.sea.message.moderate_any": "最近の会話を表示し、ルール違反のメッセージを非表示にできます。操作履歴はチャットに保存されます。",
  "permission.description.sea.user.mute_any": "ログイン済みユーザー、ゲストの識別情報、または発信元 IP に期限付きまたは長期の発言制限を設定できます。期限や理由の変更、制限の解除もできます。",
  "permission.description.comment.manage_any": "コメントを非表示にしたり、非表示のコメントを表示に戻したりできます。削除済みのコメントは復元できません。",
  "permission.description.timeline.use": "タイムラインを有効にして、選択した公開アクティビティを記録できます。公開タイムラインは権限なしで閲覧できます。権限を取り消すと新規記録が停止します。既存の履歴は保持され、ユーザーは引き続きタイムラインを無効にできます。",
  "permission.description.timeline.status.create": "有効なタイムラインに独立したひとことを投稿できます。タイムラインを有効にして活動を記録する権限も必要です。",
  "permission.description.timeline.status.delete_own": "自分のひとことを削除して本文を消去できます。タイムラインの有効・無効に関係なく利用できます。",
  "permission.description.timeline.event.delete_own": "タイムラインから自分のアクティビティを削除できます。元のお気に入り、コメント、掲示板の投稿などの内容は保持されます。",
  "permission.description.timeline.status.moderate_any": "ルール違反のひとことを削除して本文を消去し、モデレーションログに記録します。この権限には編集や復元は含まれません。",
  "permission.description.timeline.event.moderate_any": "ルール違反のアクティビティを削除し、モデレーションログに記録します。元の内容は保持されます。この権限には復元は含まれません。",
  "permission.description.timeline.follow.create": "ほかの有効なユーザーをフレンドに追加できます。相手による追加や自分のタイムラインの有効化は不要です。フレンド追加後も相手の公開範囲が適用されます。",
  "permission.description.timeline.status.like": "公開のひとことにいいねしたり、自分のいいねを取り消したりできます。自分のタイムラインの有効・無効に関係なく利用できます。",
  "permission.description.timeline.reply.create": "公開のひとことに絵文字や画像付きで返信できます。メンションには対応していません。自分のタイムラインの有効・無効に関係なく利用できます。",
  "permission.description.timeline.reply.delete_own": "自分の返信を削除して本文を消去できます。元のひとことは保持されます。",
  "permission.description.timeline.reply.moderate_any": "ルール違反の返信を削除して本文を消去し、非公開のモデレーションログに記録します。",
  "permission.description.timeline.follow.delete_own": "自分が追加したフレンド関係を解除できます。相手が始めた関係は保持され、他人のフレンド関係を追加・解除する権限は付与されません。",
  "permission.description.forum.use": "トピックや返信の投稿、自分の投稿の編集・削除、いいね、通報、画像のアップロードができます。公開の掲示板は権限なしで閲覧できます。",
  "permission.description.forum.content.moderate_any": "モデレーションの文脈を確認し、公開内容の非表示・復元、トピックのロック・解除、通報への対応ができます。ダイレクトメッセージは対応する通報からのみ会話を閲覧できます。",
  "permission.description.forum.topic.feature_any": "トピックの特集指定と解除、タグの訂正ができます。通報処理やサイト全体のタグ管理の権限は含まれません。",
  "permission.description.forum.topic.sage_any": "トピックの SAGE を設定または解除できます。SAGE が付いたトピックは掲示板一覧の末尾に表示されます。",
  "permission.description.forum.tag.manage": "掲示板タグの名前変更、統合、無効化、非表示、復元ができます。",
  "permission.description.emoji.defaults.manage": "キャラクターの顔グラフィックから既定の絵文字を選び、順序を変更できます。",
  "permission.description.archive_version.read_private": "非表示や削除済みのバージョンを含め、管理画面のアーカイブ一覧を表示できます。",
  "permission.description.archive_version.update": "アーカイブの出典と公開状態を変更できます。削除済みのバージョンは先に復元が必要です。完全削除後は編集できません。",
  "permission.description.archive_version.delete_own": "自分が担当する作品のアーカイブをごみ箱に移動できます。ほかの人がアップロードしたバージョンも対象です。",
  "permission.description.archive_version.delete_any": "任意の作品のアーカイブをごみ箱に移動できます。ストレージ上のファイルはその時点では削除されません。",
