  "permission.description.archive_version.set_current": "条件を満たす公開済みアーカイブを現行バージョンに設定し、ダウンロードとプレイに使うバージョンを変更できます。",
  "permission.description.import_job.create": "自分のアップロードタスクを作成、閲覧、再開できます。完了するには事前確認、ファイルのアップロード、送信の権限も必要です。",
  "permission.description.import_job.preflight_own": "自分のタスクのファイル一覧と不足ファイルを確認し、元ファイルのアップロード完了を検証できます。",
  "permission.description.storage_object.upload": "アップロード可能な自分のタスクにファイルとコアパックをアップロードできます。公開には別の権限が必要です。",
  "permission.description.import_job.commit_own": "作品情報を確認して自分のタスクを送信できます。既存作品の更新には、その作品の編集権限も必要です。",
  "permission.description.import_job.cancel_own": "まだキャンセル可能な自分のアップロードタスクをキャンセルできます。ほかのユーザーのタスクは対象外です。",
  "permission.description.user.rename_own": "プロフィールから自分の表示名を変更できます。",
  "permission.description.user.read": "権限階層が自分より下位のユーザーを表示できます。自分自身と同位以上のユーザーは対象外です。",
  "permission.description.user.status.update": "権限階層が下位のユーザーのアカウント状態を変更できます。無効化するとセッションが取り消されます。退会済みのアカウントは有効化できません。",
  "permission.description.user.role.assign": "権限階層が下位の有効なユーザーに対して、下位のロールを変更できます。自分自身の変更、基本ロールの解除、ルートロールの付与はできません。",
  "permission.description.inbox.role_request.resolve": "管理者はロール申請を承認または却下できます。ロール付与権限と階層条件を満たす必要があり、管理者ロールの申請はスーパー管理者のみ処理できます。",
  "permission.description.system.dashboard.read": "サイト概要、運用統計、アップロードタスクの記録を表示できます。ほかの管理権限は別途必要です。",
  "permission.description.system.maintenance.run": "データ整合性チェックとストレージのクリーンアップのプレビューを表示できます。実際の削除には別の権限が必要です。",
  "permission.description.storage.gc.sweep": "条件を満たすストレージオブジェクトを削除できます。削除後のアーカイブは復元できません。実行前に確認が必要です。",
  "permission.description.audit.read": "ログイン、アカウントのロール変更、管理画面での保守操作の記録を閲覧できます。",
  "permission.description.genre.manage": "ジャンルグループを表示して統合できます。作品の原文と各ジャンル名は保持されます。",
  "permission.description.work.lookup_non_deleted": "関連付けや作品リストへの追加時に公開作品を検索できます。管理権限があっても候補の範囲は広がりません。",
  "permission.description.work.read_private": "非表示や削除済みの作品を含む、管理画面の作品一覧を表示できます。",
  "permission.description.work.metadata.update_any": "任意の作品の名前、紹介文、タグ、作者、キャラクター、表示用情報を編集できます。アーカイブ内容、出典、外部リンクには別の権限が必要です。",
  "permission.description.work.distribution.update_any": "任意の作品のアーカイブ内容、出典、外部リンク、ダウンロード方式を変更できます。アーカイブのアップロードには別の権限が必要です。作品情報や状態の変更権限は含みません。",
  "permission.description.work.status.update_any": "任意の作品の公開範囲とトップページ表示を変更し、削除や復元ができます。",
  "permission.description.work.maintainer.manage_any": "作品メンテナーを追加または解除できます。",
  "permission.description.work.merge_any": "重複作品を統合できます。通常の関連付けと翻訳版の関連付けを削除する権限も必要です。",
  "permission.description.creator.metadata.update_public": "公開ページから作者名、別名、ウェブサイト、紹介文、アバターを編集できます。保存後すぐに反映され、変更は記録されます。",
  "permission.description.creator.read_private": "公開作品に関連付けられていない作者も含め、管理画面の作者一覧を表示できます。",
  "permission.description.creator.metadata.update_any": "作者名、別名、説明、アバターを編集できます。作者の統合には別の権限が必要です。",
  "permission.description.creator.merge_any": "重複する作者とその関連付けを統合できます。",
  "permission.description.character.admin.read": "キャラクター管理一覧、分類ツリー、素材の編集画面にアクセスできます。キャラクターの基本情報と公開素材はこの権限なしで閲覧できます。",
  "permission.description.character.create": "管理画面でキャラクターを作成できます。一致する既存のキャラクターがある場合は、その名前や別名を変更せず既存の ID を返します。作品投稿時の登場キャラクター登録には作品側の権限が適用されます。",
  "permission.description.character.metadata.update_any": "キャラクターの中国語名、日本語名、別名、紹介文を編集できます。",
  "permission.description.character.merge_any": "重複キャラクターの関連作品、所属分類、出典、コメント、素材を統合先に移し、統合元を削除できます。",
  "permission.description.character.portrait.manage_any": "既存の顔グラフィック、歩行グラフィック、モンスター・戦闘グラフィック、イラストなどを関連付けまたは解除し、既定の顔グラフィックを設定または解除できます。",
  "permission.description.character.portrait.upload": "キャラクター素材をアップロードして公開し、指定したキャラクターに関連付けられます。ほかの関連付けと既定の顔グラフィックは保持されます。",
  "permission.description.character_category.create": "最上位または下位の分類を作成し、名前、出典、親分類を指定できます。",
