  "permission.description.character_membership.update": "所属先での表示名を変更したり、所属を別の分類に移したりできます。キャラクター自体とほかの所属は保持されます。",
  "permission.description.character_membership.delete": "指定の分類からキャラクターの所属を解除できます。キャラクター自体とほかの所属は保持されます。",
  "permission.description.character_index.reorder": "同階層の分類とキャラクターの混在した表示順を調整できます。分類階層やキャラクターの所属は保持されます。",
  "permission.description.character.sources.update_any": "キャラクター自体の出典リンクを追加、編集、削除、並べ替えできます。分類の出典と所属は保持されます。",
  "permission.description.tag.read_private": "公開作品に使われていないタグを含め、管理画面でタグ一覧を表示できます。",
  "permission.description.tag.metadata.update_any": "タグの名前空間と説明を編集できます。タグ名の変更、統合、削除はできません。",
  "permission.description.work.update_own": "自分が担当する作品を編集、非表示、削除したり、メンテナーを追加して申請を審査したりできます。担当資格は作品のメンテナー一覧で決まります。",
  "permission.description.work.external_create": "外部ダウンロードリンクで配布する作品を作成できます。サイト内アーカイブのアップロードには別の権限が必要です。",
  "permission.description.relation.create": "自分がメンテナーとして登録されている作品に関連付けを追加できます。逆方向の関連付けを自動作成する際、相手作品のメンテナー資格は不要です。",
