  "permission.description.translation_relation.create_any": "任意の原版と翻訳版を関連付けられます。",
  "permission.description.translation_relation.create": "自分がメンテナーとして登録されている作品について原語版と翻訳版を関連付けられます。逆方向の関連付けを自動作成する際、相手作品のメンテナー資格は不要です。",
  "permission.description.translation_relation.delete_any": "原版と翻訳版の関連付けを削除できます。",
  "permission.description.catalog.create": "自分の作品リストを作成できます。",
