  "about.intro.archive": "VIPRPG中文保管庫（VIPRPG.org、以下「当サイト」）は、中国語圏のVIPRPGファンが開発した、中国語圏のコミュニティ向けの作品保管庫です。",
  "about.intro.networkBefore": "当サイトは",
  "about.intro.networkAside": "备案（インターネット情報サービスの届出）が面倒なので",
  "about.intro.networkAfter": "誇りを持ってCloudflareのネットワークサービスを利用しています！",
  "about.intro.access": "中国本土でもたぶんアクセスできます。つながらない地域では、各自でなんとかしてください……",
  "about.features": "ここでは何ができる？",
  "about.features.download": "保管庫なので、もちろんRPGツクール2000系の作品を保存し、ダウンロードできるようにしています。",
  "about.features.welcome": "中国語訳、オリジナル作品、原版の保存はもちろん、VIPRPG以外のRM2K作品の記録も歓迎します。",
  "about.features.moreBefore": "そのほかにも、",
  "about.features.moreAside": "正直、わけがわからないほど",
  "about.features.moreAfter": "たくさんの機能があります。",
  "about.features.organize": "登場キャラクターや作者、タグなどの情報を作品に登録でき、コメント、お気に入り、作品リスト機能で作品の整理や検索ができます。",
  "about.features.play": "ブラウザで遊んだり、Android端末でEasyRPGにインポートしたりできます。",
  "about.features.directory": "各種リンクを集めたリンク集もあります。それに、正直誰かが使うかどうか考えもしなかった掲示板も……",
  "about.features.explore": "あとは自分で探索してみてください！（何を作ったか自分でも忘れました）",
  "about.rules": "ここで禁止されていることは？",
  "about.rules.posts": "当然ですが、ヘイトスピーチ、広告投稿、荒らし目的の投稿などは削除します。",
  "about.rules.nonVip": "VIPRPG以外の作品をアップロードする場合、問答無用で削除されることがあります。（理由は後述）",
  "about.rules.watchBefore": "特に、当サイトでは",
  "about.rules.watchAfter": "に関連する内容や作品への言及を禁止しています。",
  "about.rules.changes": "禁止事項は予告なく追加されることがあります。どの程度の処分になるかは管理人の気分次第です。",
  "about.storage": "作品はどうやって保存している？",
  "about.storage.overlap": "VIPRPGの作品では素材の重複が非常に多く、闇市のシバルバーの顔グラが、1000本のksgのうち500本に出てくることもあります。",
  "about.storage.shared": "そこで、同一の素材を複数の作品で共有できる保存システムを作りました。",
  "about.storage.core": "マップやゲームのデータベースなどの主要ファイルはまとめて保存し、顔グラや音楽などの素材はファイルの内容で重複を判定します。",
  "about.storage.dedup": "内容が同じ素材はひとつだけ保存します。当サイト独自の「RTP」のようなものです。",
  "about.storage.zip": "ダウンロード時には、作品ごとのファイル一覧をもとに必要なファイルを取り出し、ZIPにまとめ直します。",
  "about.storage.savings": "この仕組みで、作品ごとの保存容量を大幅に削減できます。",
  "about.storage.limit": "一方、RPGツクール2000系以外の作品を保存できないという欠点があります。",
  "about.storage.external": "そのため、外部リンクを登録できるようにしています。2K系以外の作品は、ご自身のオンラインストレージを使って登録できます。",
  "about.storage.hostsBefore": "外部リンクには",
  "about.storage.hostsLanzou": "藍奏雲",
  "about.storage.hostsSeparator": "、",
  "about.storage.hostsOr": "、または",
  "about.storage.hostsAfter": "をおすすめします。",
  "about.storage.update": "追記：サイトを運営するなかで、もうひとつ問題が見えてきました。",
  "about.storage.unshared": "VIPRPG以外の作品に他の作品と共有できない素材が大量に含まれていると、費用のかかるオブジェクトストレージを圧迫します。",
  "about.storage.cleanup": "そのため、共有されない素材の使用量に応じて、VIPRPG以外の作品のアーカイブを予告なく削除することがあります。",
  "about.storage.submit": "作品を登録したい場合は、当サイトの保存容量を使わない外部リンクをご利用ください。",
  "about.thanks": "謝辞",
  "about.thanks.inspiration": "当サイトの設計は、H5mota、Bangumi、Mastodon、Ticalc、Bilibili、百度貼吧、NGA国家地理などの優れた実装を参考にしています。",
  "about.thanks.easyrpg": "開発には、EasyRPGプロジェクトの開発者が制作した優れたWeb Playerとliblcfライブラリを使用しています。",
  "about.thanks.community": "当サイトは、中国語圏のコミュニティと本場のVIPRPGファン一人ひとりの支えがあってこそ生まれました。",
