  "relation.guide.adaptation.text": "既存の物語をゲーム化するなど、明確な翻案関係がある作品です。単なる移植やエンジンの変更は、それだけでは翻案に当たりません。",
  "relation.guide.prequel.text": "関連作品は現在の作品より前の物語を描いているか、シリーズの先行作として明示されています。",
  "relation.guide.prequel.example": "第2作のページから第1作を関連付ける場合は「前日譚」を選びます。",
  "relation.guide.sequel.text": "関連作品は現在の作品の後の物語を描いているか、シリーズの後続作として明示されています。",
  "relation.guide.sequel.example": "第1作のページから第2作を関連付ける場合は「続編」を選びます。",
  "relation.guide.same_setting.text": "同じ世界や時間軸を舞台としますが、直接の前日譚・続編ではありません。登場人物は異なる場合も、一部が共通する場合もあります。",
  "relation.guide.alternative_setting.text": "主な登場人物は同じですが、世界、時間軸、または背景設定が異なります。",
  "relation.guide.alternative_version.text": "基本設定と主な登場人物を共有し、物語、展開、または結末を異なる形で描いています。",
  "relation.guide.character.text": "同じキャラクターが明確に登場しますが、物語に連続性はありません。VIPRPG で広く使われるキャラクターは、まず「登場キャラクター」に記録してください。",
  "relation.guide.collaboration.text": "現在の作品は、関連作品のキャラクターや内容を明確に取り入れています。関連先はその内容の出典で、この関連は一方向です。",
  "relation.guide.collaboration.example": "A が B のキャラクターを取り入れた場合、A のページで B を関連付けて「コラボレーション」を選びます。",
  "relation.guide.version.text": "関連作品は現在の作品のリメイク、移植、または拡張版です。物語と登場人物はほぼ同じで、グラフィック、音楽、またはシステムが変更されています。",
  "relation.guide.version.example": "元の作品のページからリメイク版を関連付ける場合は「別バージョン」を選びます。",
  "relation.guide.main_version.text": "関連作品は、現在のリメイク、移植、または拡張版の元になった初出のバージョンです。",
  "relation.guide.main_version.example": "リメイク版のページから初出のバージョンを関連付ける場合は「元のバージョン」を選びます。",
  "relation.guide.collection.text": "関連作品は、現在の作品を実際に収録している作品集です。ユーザーがまとめたおすすめやイベントの一覧には、サイトの作品リストを使ってください。",
  "relation.guide.collection.example": "単独作品のページから、その作品を含む作品集を関連付ける場合は「収録作品集」を選びます。",
  "relation.guide.in_collection.text": "関連作品は、現在の作品集に実際に収録されている作品です。",
  "relation.guide.in_collection.example": "作品集のページから収録作品を関連付ける場合は「収録作品」を選びます。",
  "relation.guide.original.text": "関連作品は現在の翻訳版の原語版です。原語版と翻訳版は別々の項目で、言語が異なる必要があります。翻訳版に指定できる原語版は1つです。",
  "relation.guide.original.example": "中国語翻訳版のページから日本語原版を関連付ける場合は「原語版」を選びます。",
  "relation.guide.translation.text": "関連作品は現在の作品を別の言語に翻訳したものです。翻訳のみの場合は「別バージョン」や「翻案」ではなく、翻訳の関連を使います。",
  "relation.guide.translation.example": "日本語原版のページから中国語翻訳版を関連付ける場合は「翻訳版」を選びます。",
  "relation.guide.intro": "現在の作品を基準に、関連先がどのような関係にあるかを選びます。たとえば、第2作のページから第1作を関連付ける場合は「前日譚」を選びます。",
  "relation.guide.scope": "作品の関連は、物語、設定、バージョン、収録に明確なつながりがある場合に使います。作者、素材、一般的な VIPRPG キャラクターが共通するだけなら、通常は関連付けは不要です。判断できない場合は追加を見送れます。",
  "relation.guide.reciprocal": "「コラボレーション」を除き、逆方向の関連は自動で作られます。相手の作品ページで追加する必要はありません。「前日譚」を追加すると、相手側には「続編」と表示されます。",
